import * as DialogPrimitive from "@rn-primitives/dialog";
import { type ComponentProps, useEffect, useState } from "react";
import { Animated, useWindowDimensions } from "react-native";
import { AnimatedView } from "../../lib/animated.js";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { cn } from "../../lib/utils.js";

/** How long the sheet takes to slide in or out, in milliseconds. */
const SLIDE_DURATION = 220;

/** Props for {@link BottomSheet}. */
export type BottomSheetProps = ComponentProps<typeof DialogPrimitive.Root>;

/**
 * A panel that rises from the bottom of the screen.
 *
 * The native answer to a menu, an option list, or a short form — everything
 * a web app would hang in a dropdown or a popover, where a thumb cannot
 * comfortably reach. Built on the dialog primitive, so it is modal and needs
 * a `<PortalHost />` in the root layout.
 *
 * This has no web counterpart in the catalog: on a desktop the same job is
 * done by DropdownMenu, Popover or Dialog.
 * @param props - {@link BottomSheetProps}
 * @returns The sheet root
 * @example
 * ```tsx
 * <BottomSheet open={open} onOpenChange={setOpen}>
 *   <BottomSheetContent>
 *     <BottomSheetTitle>Sort by</BottomSheetTitle>
 *     <RadioGroup value={sort} onValueChange={setSort}>…</RadioGroup>
 *   </BottomSheetContent>
 * </BottomSheet>
 * ```
 */
export function BottomSheet(props: BottomSheetProps) {
	return <DialogPrimitive.Root {...props} />;
}

/** Props for {@link BottomSheetTrigger}. */
export type BottomSheetTriggerProps = ComponentProps<typeof DialogPrimitive.Trigger>;

/**
 * Opens the sheet.
 * @param props - {@link BottomSheetTriggerProps}
 * @returns The trigger
 */
export function BottomSheetTrigger(props: BottomSheetTriggerProps) {
	return <DialogPrimitive.Trigger {...props} />;
}

/** Props for {@link BottomSheetContent}. */
export interface BottomSheetContentProps
	extends ComponentProps<typeof DialogPrimitive.Content> {
	/** Name of the `PortalHost` to render into, when the app mounts more than one. */
	portalHost?: string;
}

/**
 * The sheet panel. Slides up from the bottom edge and pads itself past the
 * home indicator.
 * @param props - {@link BottomSheetContentProps}
 * @returns The portalled sheet
 */
export function BottomSheetContent({
	className,
	portalHost,
	children,
	style,
	...props
}: BottomSheetContentProps) {
	const insets = useSafeAreaInsets();
	const { height } = useWindowDimensions();
	// `useState` with an initialiser, not `useRef(new Animated.Value(…))`:
	// the latter constructs a fresh Value on every render and throws it away.
	const [translateY] = useState(() => new Animated.Value(height));

	useEffect(() => {
		const animation = Animated.timing(translateY, {
			toValue: 0,
			duration: SLIDE_DURATION,
			useNativeDriver: true,
		});
		animation.start();
		return () => {
			animation.stop();
		};
	}, [translateY]);

	return (
		<DialogPrimitive.Portal hostName={portalHost}>
			<DialogPrimitive.Overlay className="absolute inset-0 justify-end bg-black/50">
				{/*
				 * `asChild` onto an Animated.View is load-bearing, not a style
				 * choice: the primitive's Content renders a plain View, and
				 * React Native throws "You passed an Animated.Value to a normal
				 * component" the moment it processes the transform. Slot
				 * forwards role, aria-modal and onAccessibilityEscape, so the
				 * dialog semantics are unchanged.
				 */}
				<DialogPrimitive.Content asChild {...props}>
					<AnimatedView
						className={cn(
							"w-full gap-4 rounded-t-2xl border-t border-border bg-background px-6 pt-6",
							className,
						)}
						// The consumer's style goes last so it can override the
						// padding, while the transform is still applied.
						style={[
							{ transform: [{ translateY }], paddingBottom: insets.bottom + 24 },
							style,
						]}
					>
						{children}
					</AnimatedView>
				</DialogPrimitive.Content>
			</DialogPrimitive.Overlay>
		</DialogPrimitive.Portal>
	);
}

/** Props for {@link BottomSheetTitle} and {@link BottomSheetDescription}. */
export type BottomSheetTextProps = ComponentProps<typeof DialogPrimitive.Title>;

/**
 * The sheet's title. Announced when it opens, so always include one.
 * @param props - {@link BottomSheetTextProps}
 * @returns The title
 */
export function BottomSheetTitle({ className, ...props }: BottomSheetTextProps) {
	return (
		<DialogPrimitive.Title
			className={cn("text-lg font-semibold text-foreground", className)}
			{...props}
		/>
	);
}

/**
 * A muted line under the title.
 * @param props - {@link BottomSheetTextProps}
 * @returns The description
 */
export function BottomSheetDescription({ className, ...props }: BottomSheetTextProps) {
	return (
		<DialogPrimitive.Description
			className={cn("text-sm text-muted-foreground", className)}
			{...props}
		/>
	);
}

/** Props for {@link BottomSheetClose}. */
export type BottomSheetCloseProps = ComponentProps<typeof DialogPrimitive.Close>;

/**
 * Dismisses the sheet. Wrap a Button with `asChild`.
 * @param props - {@link BottomSheetCloseProps}
 * @returns The close control
 */
export function BottomSheetClose(props: BottomSheetCloseProps) {
	return <DialogPrimitive.Close {...props} />;
}

import { createContext, useContext } from "react";

/**
 * Class names a parent wants applied to the `<Text>` elements inside it.
 *
 * React Native text does not inherit colour or size from its container the
 * way DOM text does, so a `Button` cannot make its label
 * `text-primary-foreground` by styling itself. Instead it provides that
 * class here and `Text` reads it. Same pattern React Native Reusables
 * uses; kept as a tiny shared module so every component agrees on it.
 */
export const TextClassContext = createContext<string | undefined>(undefined);

/**
 * Read the class names the nearest text-styling ancestor provided.
 * @returns The inherited class string, or undefined outside any provider
 */
export function useTextClass(): string | undefined {
	return useContext(TextClassContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind-aware conflict resolution.
 *
 * Deliberately a copy of the web helper rather than an import from
 * `@hex-core/components`: that package is React DOM, and `hex add` ships
 * this file into the consumer's project alongside each component anyway.
 * NativeWind's platform prefixes (`ios:`, `android:`, `native:`) are
 * unknown to tailwind-merge and pass through untouched.
 * @param inputs - Class values (strings, arrays, conditionals) to merge
 * @returns The merged class string with later Tailwind utilities winning
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
